insert into public.roadwise_questions select * from jsonb_populate_recordset(null::public.roadwise_questions, '[{"id": "parivahan-001", "category": "rules", "prompt": "Near a pedestrian crossing, when the pedestrians are waiting to cross the road, you should", "options": ["Sound horn and proceed", "Slow down, sound horn and pass", "Stop the vehicle and wait till the pedestrians cross the road and then proceed"], "answer": 2, "image": null, "explanation": "The published Parivahan question bank identifies “Stop the vehicle and wait till the pedestrians cross the road and then proceed” as the correct answer.", "source_url": "https://parivahan.gov.in/sites/default/files/DownloadForm/STALL_QB_ENGLISH_NEW.pdf", "source_ref": "Question 1, PDF page 1", "imported_at": "2026-10-23", "topic": "Safe driving"}, {"id": "parivahan-003", "category": "rules", "prompt": "You are approaching a narrow bridge, another vehicle is about to enter the bridge from opposite side you should", "options": ["Increase the speed and try to cross the bridge as fast as possible", "Put on the head light and pass the bridge", "Wait till the other vehicle crosses the bridge and then proceed"], "answer": 2, "image": null, "explanation": "The published Parivahan question bank identifies “Wait till the other vehicle crosses the bridge and then proceed” as the correct answer.", "source_url": "https://parivahan.gov.in/sites/default/files/DownloadForm/STALL_QB_ENGLISH_NEW.pdf", "source_ref": "Question 3, PDF page 1", "imported_at": "2026-10-23", "topic": "Safe driving"}, {"id": "parivahan-005", "category": "rules", "prompt": "When a vehicle is involved in an accident causing injury to any person", "options": ["Take the vehicle to the nearest police station and report the accident", "Stop the vehicle and report to the police station", "Take all reasonable steps to secure medical attention to the injured and report to the nearestpolice station within 24 hours"], "answer": 2, "image": null, "explanation": "The published Parivahan question bank identifies “Take all reasonable steps to secure medical attention to the injured and report to the nearestpolice station within 24 hours” as the correct answer.", "source_url": "https://parivahan.gov.in/sites/default/files/DownloadForm/STALL_QB_ENGLISH_NEW.pdf", "source_ref": "Question 5, PDF page 1", "imported_at": "2026-10-23", "topic": "Safe driving"}, {"id": "parivahan-007", "category": "rules", "prompt": "On a road designated as one way", "options": ["Parking is prohibited", "Overtaking is prohibited", "Should not drive in reverse gear"], "answer": 2, "image": null, "explanation": "The published Parivahan question bank identifies “Should not drive in reverse gear” as the correct answer.", "source_url": "https://parivahan.gov.in/sites/default/files/DownloadForm/STALL_QB_ENGLISH_NEW.pdf", "source_ref": "Question 7, PDF page 1", "imported_at": "2026-10-23", "topic": "Safe driving"}, {"id": "parivahan-009", "category": "rules", "prompt": "You can overtake a vehicle in front", "options": ["Through the right side of that vehicle", "Through the left side", "Through the left side, if the road is wide"], "answer": 0, "image": null, "explanation": "The published Parivahan question bank identifies “Through the right side of that vehicle” as the correct answer.", "source_url": "https://parivahan.gov.in/sites/default/files/DownloadForm/STALL_QB_ENGLISH_NEW.pdf", "source_ref": "Question 9, PDF page 1", "imported_at": "2026-10-23", "topic": "Safe driving"}, {"id": "parivahan-015", "category": "rules", "prompt": "Validity of learners licence", "options": ["Till the driving licence is obtained", "6 months", "30 days"], "answer": 1, "image": null, "explanation": "The published Parivahan question bank identifies “6 months” as the correct answer.", "source_url": "https://parivahan.gov.in/sites/default/files/DownloadForm/STALL_QB_ENGLISH_NEW.pdf", "source_ref": "Question 15, PDF page 2", "imported_at": "2026-10-23", "topic": "Safe driving"}, {"id": 